package workstore

// Indexed ownership columns are generated from the typed payload, so an update
// cannot silently diverge between the stored object and its relational guards.
// All writes also validate the corresponding core/work value before SQL.
var schemaV1 = []string{
	`CREATE TABLE principals (id TEXT PRIMARY KEY NOT NULL CHECK(id<>''), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0), payload TEXT NOT NULL CHECK(json_valid(payload)))`,
	`CREATE TABLE roles (id TEXT PRIMARY KEY NOT NULL CHECK(id<>''), revision INTEGER NOT NULL CHECK(revision>0), payload TEXT NOT NULL CHECK(json_valid(payload)))`,
	`CREATE TABLE teams (id TEXT PRIMARY KEY NOT NULL CHECK(id<>''), revision INTEGER NOT NULL CHECK(revision>0), payload TEXT NOT NULL CHECK(json_valid(payload)))`,
	`CREATE TABLE team_members (team_id TEXT NOT NULL REFERENCES teams(id),role_id TEXT NOT NULL REFERENCES roles(id),revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(team_id,role_id))`,
	`CREATE TABLE scopes (
 id TEXT PRIMARY KEY NOT NULL CHECK(id<>''),revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 kind TEXT GENERATED ALWAYS AS (json_extract(payload,'$.kind')) STORED NOT NULL,
 principal_id TEXT GENERATED ALWAYS AS (nullif(json_extract(payload,'$.principal_id'),'')) STORED REFERENCES principals(id),
 role_id TEXT GENERATED ALWAYS AS (nullif(json_extract(payload,'$.role_id'),'')) STORED REFERENCES roles(id),
 team_id TEXT GENERATED ALWAYS AS (nullif(json_extract(payload,'$.team_id'),'')) STORED REFERENCES teams(id),
 project_id TEXT GENERATED ALWAYS AS (nullif(json_extract(payload,'$.project_id'),'')) STORED REFERENCES projects(id) DEFERRABLE INITIALLY DEFERRED,
 tenant TEXT GENERATED ALWAYS AS (nullif(json_extract(payload,'$.tenant'),'')) STORED,
 chat_id TEXT GENERATED ALWAYS AS (nullif(json_extract(payload,'$.chat_id'),'')) STORED,
 bootstrap_operation_id TEXT GENERATED ALWAYS AS (nullif(json_extract(payload,'$.bootstrap_operation_id'),'')) STORED REFERENCES operations(id) DEFERRABLE INITIALLY DEFERRED,
 binding_generation INTEGER GENERATED ALWAYS AS (json_extract(payload,'$.binding_generation')) STORED,
 CHECK((kind='personal' AND role_id IS NOT NULL AND principal_id IS NOT NULL AND project_id IS NULL AND team_id IS NULL) OR (kind='bootstrap' AND role_id IS NOT NULL AND principal_id IS NOT NULL AND tenant IS NOT NULL AND chat_id IS NOT NULL AND bootstrap_operation_id IS NOT NULL AND binding_generation>=0 AND project_id IS NULL AND team_id IS NULL) OR (kind='project' AND role_id IS NULL AND principal_id IS NULL AND project_id IS NOT NULL AND team_id IS NOT NULL) OR (kind='library' AND role_id IS NULL AND principal_id IS NULL AND project_id IS NULL AND team_id IS NULL AND tenant IS NULL AND chat_id IS NULL AND bootstrap_operation_id IS NULL)))`,
	`CREATE UNIQUE INDEX personal_scope_owner ON scopes(principal_id,role_id) WHERE kind='personal'`,
	`CREATE UNIQUE INDEX bootstrap_scope_channel ON scopes(tenant,chat_id,binding_generation) WHERE kind='bootstrap'`,
	`CREATE TABLE projects (
 id TEXT PRIMARY KEY NOT NULL CHECK(id<>''),revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL UNIQUE REFERENCES scopes(id),
 team_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.team_id')) STORED NOT NULL REFERENCES teams(id),
 leader_role_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.leader_role_id')) STORED NOT NULL REFERENCES roles(id))`,

	`CREATE TABLE project_members (project_id TEXT NOT NULL REFERENCES projects(id),role_id TEXT NOT NULL REFERENCES roles(id),revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(project_id,role_id))`,
	`CREATE TABLE role_bot_bindings (id TEXT PRIMARY KEY NOT NULL REFERENCES roles(id),revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)))`,
	`CREATE TABLE channel_bindings (tenant TEXT NOT NULL,chat_id TEXT NOT NULL,generation INTEGER NOT NULL CHECK(generation>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 project_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.project_id')) STORED NOT NULL REFERENCES projects(id),
 active INTEGER GENERATED ALWAYS AS (json_extract(payload,'$.active')) STORED NOT NULL,
 PRIMARY KEY(tenant,chat_id,generation))`,
	`CREATE UNIQUE INDEX active_channel_project ON channel_bindings(tenant,chat_id) WHERE active=1`,
	`CREATE TABLE contexts (
 id TEXT PRIMARY KEY NOT NULL CHECK(id<>''),revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id),
 role_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.role_id')) STORED NOT NULL REFERENCES roles(id),
 workstream TEXT GENERATED ALWAYS AS (json_extract(payload,'$.workstream')) STORED NOT NULL,
 UNIQUE(scope_id,role_id,workstream),UNIQUE(id,scope_id,role_id))`,
	`CREATE TABLE locations (
 id TEXT PRIMARY KEY NOT NULL CHECK(id<>''),revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)))`,
	`CREATE TABLE workers (
 id TEXT PRIMARY KEY NOT NULL CHECK(id<>''),revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 context_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.context_id')) STORED NOT NULL,
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL,
 role_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.role_id')) STORED NOT NULL,
 generation INTEGER GENERATED ALWAYS AS (json_extract(payload,'$.generation')) STORED NOT NULL CHECK(generation>0),
 state TEXT GENERATED ALWAYS AS (json_extract(payload,'$.state')) STORED NOT NULL,
 backend TEXT GENERATED ALWAYS AS (json_extract(payload,'$.backend')) STORED NOT NULL,
 native_namespace TEXT GENERATED ALWAYS AS (nullif(json_extract(payload,'$.native_namespace'),'')) STORED,
 native_session_id TEXT GENERATED ALWAYS AS (nullif(json_extract(payload,'$.native_session_id'),'')) STORED,
 FOREIGN KEY(context_id,scope_id,role_id) REFERENCES contexts(id,scope_id,role_id),UNIQUE(id,context_id,scope_id),
 CHECK((native_namespace IS NULL)=(native_session_id IS NULL)))`,
	`CREATE UNIQUE INDEX native_session_owner ON workers(backend,native_namespace,native_session_id) WHERE state<>'retired' AND native_session_id IS NOT NULL`,
	`CREATE TABLE tasks (
 id TEXT PRIMARY KEY NOT NULL CHECK(id<>''),revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id),
 state TEXT GENERATED ALWAYS AS (json_extract(payload,'$.state')) STORED NOT NULL,
 owner_role_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.owner_role_id')) STORED NOT NULL REFERENCES roles(id),
 UNIQUE(id,scope_id))`,
	`CREATE INDEX tasks_scope_state ON tasks(scope_id,state)`,
	`CREATE TABLE messages (
 id TEXT PRIMARY KEY NOT NULL CHECK(id<>''),revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id),
 source_key TEXT UNIQUE)`,
	`CREATE TABLE bootstrap_adoptions (operation_id TEXT NOT NULL REFERENCES operations(id),source_message_id TEXT NOT NULL REFERENCES messages(id),derived_message_id TEXT NOT NULL UNIQUE REFERENCES messages(id),target_context_id TEXT NOT NULL,PRIMARY KEY(operation_id,source_message_id))`,
	`CREATE TABLE inbox (
 id TEXT PRIMARY KEY NOT NULL CHECK(id<>''),revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id),
 context_id TEXT GENERATED ALWAYS AS (nullif(json_extract(payload,'$.recipient_context_id'),'')) STORED REFERENCES contexts(id),
 role_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.recipient_role_id')) STORED NOT NULL REFERENCES roles(id),
 event_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.event_id')) STORED NOT NULL,
 task_id TEXT GENERATED ALWAYS AS (nullif(json_extract(payload,'$.task_id'),'')) STORED REFERENCES tasks(id),
 message_id TEXT GENERATED ALWAYS AS (nullif(json_extract(payload,'$.message_id'),'')) STORED REFERENCES messages(id),
 state TEXT GENERATED ALWAYS AS (json_extract(payload,'$.state')) STORED NOT NULL,
 claimed_attempt_id TEXT GENERATED ALWAYS AS (nullif(json_extract(payload,'$.claimed_attempt_id'),'')) STORED REFERENCES attempts(id) DEFERRABLE INITIALLY DEFERRED,
 CHECK(state IN ('pending','claimed','processed','cancelled')),
 CHECK(state NOT IN ('claimed','processed') OR claimed_attempt_id IS NOT NULL OR (state='processed' AND coalesce(json_extract(payload,'$.shell_operation_id'),'')<>'')))`,
	`CREATE UNIQUE INDEX inbox_event_target ON inbox(scope_id,role_id,coalesce(context_id,''),event_id)`,
	`CREATE INDEX inbox_ready ON inbox(role_id,context_id,state)`,
	`CREATE TABLE attempts (
 id TEXT PRIMARY KEY NOT NULL CHECK(id<>''),revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 worker_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.run_ref.worker_id')) STORED NOT NULL,
 context_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.context_id')) STORED NOT NULL,
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL,
 run_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.run_ref.run_id')) STORED NOT NULL UNIQUE,
 state TEXT GENERATED ALWAYS AS (json_extract(payload,'$.state')) STORED NOT NULL,
 command_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.command_id')) STORED NOT NULL UNIQUE,
 FOREIGN KEY(worker_id,context_id,scope_id) REFERENCES workers(id,context_id,scope_id))`,
	`CREATE UNIQUE INDEX one_active_attempt ON attempts(worker_id) WHERE state IN ('prepared','dispatch_pending','running','reconciling')`,
	`CREATE TABLE attempt_inputs (attempt_id TEXT NOT NULL REFERENCES attempts(id),inbox_id TEXT NOT NULL REFERENCES inbox(id),PRIMARY KEY(attempt_id,inbox_id))`,
	`CREATE TABLE dependencies (parent_id TEXT NOT NULL REFERENCES tasks(id),child_id TEXT NOT NULL REFERENCES tasks(id),condition TEXT NOT NULL,satisfied_by TEXT CHECK(satisfied_by IS NULL OR json_valid(satisfied_by)),PRIMARY KEY(parent_id,child_id,condition),CHECK(parent_id<>child_id))`,
	`CREATE TABLE dependency_satisfaction_history (id INTEGER PRIMARY KEY AUTOINCREMENT,parent_id TEXT NOT NULL REFERENCES tasks(id),child_id TEXT NOT NULL REFERENCES tasks(id),condition TEXT NOT NULL,child_requirements_revision INTEGER NOT NULL,child_assignment_generation INTEGER NOT NULL,source_ref TEXT NOT NULL CHECK(json_valid(source_ref)),superseded_at TEXT NOT NULL)`,
	`CREATE TABLE pause_gates (id TEXT PRIMARY KEY NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id))`,
	`CREATE TABLE operations (id TEXT PRIMARY KEY NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id),
 actor_kind TEXT GENERATED ALWAYS AS (json_extract(payload,'$.actor.kind')) STORED NOT NULL,
 actor_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.actor.id')) STORED NOT NULL,
 kind TEXT GENERATED ALWAYS AS (json_extract(payload,'$.kind')) STORED NOT NULL,
 idempotency_key TEXT GENERATED ALWAYS AS (json_extract(payload,'$.idempotency_key')) STORED NOT NULL,
 state TEXT GENERATED ALWAYS AS (json_extract(payload,'$.state')) STORED NOT NULL,
 UNIQUE(actor_kind,actor_id,scope_id,kind,idempotency_key))`,
	`CREATE INDEX operations_pending ON operations(state)`,
	`CREATE TABLE outbox (id TEXT PRIMARY KEY NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),
 operation_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.operation_id')) STORED NOT NULL REFERENCES operations(id),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id),
 state TEXT GENERATED ALWAYS AS (json_extract(payload,'$.state')) STORED NOT NULL)`,
	`CREATE INDEX outbox_pending ON outbox(state)`,
	`CREATE TABLE task_requirements (task_id TEXT NOT NULL REFERENCES tasks(id),requirements_revision INTEGER NOT NULL CHECK(requirements_revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(task_id,requirements_revision))`,
	`CREATE TABLE evidence (id TEXT PRIMARY KEY NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),
 task_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.task_id')) STORED NOT NULL REFERENCES tasks(id),
 scope_id TEXT GENERATED ALWAYS AS (json_extract(payload,'$.scope_id')) STORED NOT NULL REFERENCES scopes(id))`,
	`CREATE TABLE resource_occupancy (resource_key TEXT PRIMARY KEY NOT NULL,attempt_id TEXT NOT NULL REFERENCES attempts(id) DEFERRABLE INITIALLY DEFERRED,generation INTEGER NOT NULL CHECK(generation>0))`,
	`CREATE TABLE task_occupancy (task_id TEXT PRIMARY KEY NOT NULL REFERENCES tasks(id),attempt_id TEXT NOT NULL UNIQUE REFERENCES attempts(id) DEFERRABLE INITIALLY DEFERRED)`,
	`CREATE TABLE carrier_occupancy (instance_id TEXT NOT NULL,instance_generation INTEGER NOT NULL,process_generation INTEGER NOT NULL,attempt_id TEXT NOT NULL UNIQUE REFERENCES attempts(id) DEFERRABLE INITIALLY DEFERRED,PRIMARY KEY(instance_id,instance_generation,process_generation))`,
	`CREATE TABLE outcome_reports (attempt_id TEXT PRIMARY KEY NOT NULL REFERENCES attempts(id),request_hash TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)))`,
	`CREATE TABLE outcomes (attempt_id TEXT PRIMARY KEY NOT NULL REFERENCES attempts(id),request_hash TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)))`,
	`CREATE TABLE scheduler_cursors (id TEXT PRIMARY KEY NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),payload TEXT NOT NULL CHECK(json_valid(payload)))`,
	`CREATE TABLE native_turns (carrier_incarnation TEXT NOT NULL,session_id TEXT NOT NULL,turn_id TEXT NOT NULL,attempt_id TEXT NOT NULL REFERENCES attempts(id),payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(carrier_incarnation,session_id,turn_id))`,
	`CREATE TABLE runtime_receipts (carrier_incarnation TEXT NOT NULL,sequence INTEGER NOT NULL CHECK(sequence>0),payload_hash TEXT NOT NULL,instance_id TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),received_at TEXT NOT NULL,PRIMARY KEY(carrier_incarnation,sequence))`,
	`CREATE TABLE authority (legacy_key TEXT PRIMARY KEY NOT NULL,generation INTEGER NOT NULL CHECK(generation>0),scope_id TEXT NOT NULL REFERENCES scopes(id),state TEXT NOT NULL CHECK(state IN ('captured','quiescing','imported','committed','finalized')),payload TEXT NOT NULL CHECK(json_valid(payload)))`,
}
